('19000000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-manager@example.com','',now(),'{}','{}',now(),now()),
('19000000-0000-4000-8000-000000000003','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-advisor@example.com','',now(),'{}','{}',now(),now()),
('19000000-0000-4000-8000-000000000004','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-tech@example.com','',now(),'{}','{}',now(),now()),
('19000000-0000-4000-8000-000000000005','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-cashier@example.com','',now(),'{}','{}',now(),now()),
('19000000-0000-4000-8000-000000000006','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-viewer@example.com','',now(),'{}','{}',now(),now()),
('19000000-0000-4000-8000-000000000007','00000000-0000-0000-0000-000000000000','authenticated','authenticated','rbac-invitee@example.com','',now(),'{}','{}',now(),now()),
