('39000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000002','manager'),
('39000000-0000-4000-8000-000000000003','29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000003','advisor'),
('39000000-0000-4000-8000-000000000004','29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000004','technician'),
('39000000-0000-4000-8000-000000000005','29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000005','cashier'),
('39000000-0000-4000-8000-000000000006','29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000006','viewer'),
