insert into branches(id,organization_id,name,timezone,is_primary) values('49000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','RBAC A One','Asia/Manila',true),('49000000-0000-4000-8000-000000000003','29000000-0000-4000-8000-000000000001','RBAC A Two','Asia/Manila',false),('49000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000002','RBAC B','Asia/Manila',true);
insert into membership_branch_assignments(membership_id,organization_id,branch_id) values('39000000-0000-4000-8000-000000000004','29000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001');
insert into customers(id,organization_id,full_name) values('59000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','RBAC Customer A');
insert into vehicles(id,organization_id,customer_id,make,model) values('69000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001','Toyota','Vios');
insert into appointments(id,organization_id,branch_id,customer_id,vehicle_id,status) values('99000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001','59000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000001','confirmed'),('99000000-0000-4000-8000-000000000003','29000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000003','59000000-0000-4000-8000-000000000001','69000000-0000-4000-8000-000000000001','confirmed');
create temporary table invitation_tokens(kind text primary key,token text); grant all on invitation_tokens to authenticated;

select plan(52);
select has_table('public','role_permissions','permission matrix exists'); select has_table('public','staff_invitations','staff invitation table exists'); select has_table('public','membership_branch_assignments','branch assignment table exists');
select has_function('public','has_permission',array['uuid','permission_key'],'permission function exists'); select has_function('public','accept_staff_invitation',array['text'],'invite acceptance exists'); select has_function('public','update_staff_member',array['uuid','organization_role','boolean','uuid[]'],'staff update function exists');

set local role authenticated; set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}';
select ok(has_permission('29000000-0000-4000-8000-000000000001','staff.manage'),'owner can manage staff'); select ok(has_permission('29000000-0000-4000-8000-000000000001','organization.manage'),'owner can manage organization');
select is((select count(*) from list_staff('29000000-0000-4000-8000-000000000001'))::bigint,6::bigint,'owner can list organization staff');
insert into invitation_tokens select 'valid',create_staff_invitation('29000000-0000-4000-8000-000000000001','rbac-invitee@example.com','manager',array['49000000-0000-4000-8000-000000000001'::uuid],72);
select ok((select length(token)=64 from invitation_tokens where kind='valid'),'secure invitation token returned'); select ok((select token_hash<>(select token from invitation_tokens where kind='valid') from staff_invitations where email='rbac-invitee@example.com'),'raw invitation token is never stored'); select ok((select expires_at>now() and expires_at<=now()+interval '73 hours' from staff_invitations where email='rbac-invitee@example.com'),'invitation has bounded expiration');
select throws_ok($$select create_staff_invitation('29000000-0000-4000-8000-000000000001','owner-attempt@example.com','owner',array[]::uuid[],72)$$,'P0001','Invalid invitation','owner role cannot be invited');
select throws_ok($$select update_staff_member('39000000-0000-4000-8000-000000000001','manager',true,array[]::uuid[])$$,'P0001','Owner membership is protected','owner cannot demote owner');
select throws_ok($$select update_staff_member('39000000-0000-4000-8000-000000000001','owner',false,array[]::uuid[])$$,'P0001','Owner membership is protected','owner cannot disable owner');
select throws_ok($$select update_staff_member('39000000-0000-4000-8000-000000000009','manager',true,array[]::uuid[])$$,'42501','Staff member not found','Owner A cannot manage Org B owner');
insert into invitation_tokens select 'revoked',create_staff_invitation('29000000-0000-4000-8000-000000000001','rbac-wrong@example.com','viewer',array[]::uuid[],24);
select lives_ok($$select revoke_staff_invitation((select id from staff_invitations where email='rbac-wrong@example.com'))$$,'owner revokes pending invitation');
select is((select status::text from staff_invitations where email='rbac-wrong@example.com'),'revoked','revocation state persisted');

set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000008","role":"authenticated"}'; select throws_ok($$select accept_staff_invitation((select token from invitation_tokens where kind='valid'))$$,'42501','Invitation email does not match','wrong email cannot accept invitation'); select throws_ok($$select accept_staff_invitation((select token from invitation_tokens where kind='revoked'))$$,'P0001','Invitation is invalid','revoked invitation cannot be accepted');
set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000007","role":"authenticated"}'; select lives_ok($$select accept_staff_invitation((select token from invitation_tokens where kind='valid'))$$,'matching user accepts invitation');
select is((select role::text from organization_memberships where user_id='19000000-0000-4000-8000-000000000007'),'manager','accepted role matches invitation'); select is((select count(*) from branches)::bigint,1::bigint,'accepted branch restriction applies immediately');
select throws_ok($$select accept_staff_invitation((select token from invitation_tokens where kind='valid'))$$,'P0001','Invitation is invalid','invitation cannot be replayed');

set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000002","role":"authenticated"}';
select ok(not has_permission('29000000-0000-4000-8000-000000000001','staff.manage'),'manager cannot manage staff'); select ok(has_permission('29000000-0000-4000-8000-000000000001','inventory.manage'),'manager can manage inventory'); select throws_ok($$select create_staff_invitation('29000000-0000-4000-8000-000000000001','blocked@example.com','viewer',array[]::uuid[],72)$$,'42501','Staff management access required','manager cannot invite staff');
select throws_ok($$select update_staff_member('39000000-0000-4000-8000-000000000006','advisor',true,array[]::uuid[])$$,'42501','Staff member not found','manager cannot change roles');

set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000003","role":"authenticated"}'; select ok(has_permission('29000000-0000-4000-8000-000000000001','appointments.manage'),'advisor manages appointments'); select ok(not has_permission('29000000-0000-4000-8000-000000000001','payments.record'),'advisor cannot record payments');
set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000004","role":"authenticated"}'; select ok(has_permission('29000000-0000-4000-8000-000000000001','jobs.execute'),'technician executes assigned work'); select ok(not has_permission('29000000-0000-4000-8000-000000000001','jobs.manage'),'technician cannot manage jobs'); select is((select count(*) from branches)::bigint,1::bigint,'technician sees only assigned branch'); select is((select count(*) from appointments)::bigint,1::bigint,'technician sees only assigned branch appointments'); select is_empty($$update appointments set customer_note='attack' where id='99000000-0000-4000-8000-000000000003' returning 1$$,'technician cannot mutate invisible unassigned branch');
set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000005","role":"authenticated"}'; select ok(has_permission('29000000-0000-4000-8000-000000000001','payments.record'),'cashier records payments'); select ok(not has_permission('29000000-0000-4000-8000-000000000001','staff.manage'),'cashier cannot manage staff');
set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000006","role":"authenticated"}'; select ok(has_permission('29000000-0000-4000-8000-000000000001','reports.view'),'viewer can view reports'); select ok(not has_permission('29000000-0000-4000-8000-000000000001','customers.write'),'viewer cannot mutate customers'); select is_empty($$update customers set full_name='attack' where id='59000000-0000-4000-8000-000000000001' returning 1$$,'viewer cannot update customer');

set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}'; select lives_ok($$select update_staff_member('39000000-0000-4000-8000-000000000006','viewer',false,array[]::uuid[])$$,'owner disables staff');
set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000006","role":"authenticated"}'; select is((select count(*) from organizations)::bigint,0::bigint,'disabled staff immediately loses organization access'); select ok(not has_permission('29000000-0000-4000-8000-000000000001','reports.view'),'disabled staff immediately loses permissions');

set local "request.jwt.claims"='{"sub":"19000000-0000-4000-8000-000000000001","role":"authenticated"}'; select is((select count(*) from audit_events where event_type='staff.invited')::bigint,2::bigint,'invitations are audited'); select is((select count(*) from audit_events where event_type='staff.invitation_accepted')::bigint,1::bigint,'acceptance is audited'); select is((select count(*) from audit_events where event_type='staff.invitation_revoked')::bigint,1::bigint,'revocation is audited'); select is((select count(*) from audit_events where event_type='staff.disabled')::bigint,1::bigint,'deactivation is audited');
select throws_ok($$update organization_memberships set role='owner' where id='39000000-0000-4000-8000-000000000002'$$,'42501','permission denied for table organization_memberships','membership tables remain RPC-only');
select is((select count(*) from staff_invitations where organization_id='29000000-0000-4000-8000-000000000002')::bigint,0::bigint,'Owner A cannot read Org B invitations');
select ok(can_access_branch('29000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000003'),'owner always accesses every organization branch');
reset role; set local "request.jwt.claims"='{}'; select throws_ok($$insert into membership_branch_assignments(membership_id,organization_id,branch_id) values('39000000-0000-4000-8000-000000000002','29000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002')$$,'P0001','Staff branch organization mismatch','cross-tenant staff branch assignment rejected');
select throws_ok($$insert into staff_invitation_branches(invitation_id,branch_id) values((select id from staff_invitations where email='rbac-invitee@example.com'),'49000000-0000-4000-8000-000000000002')$$,'P0001','Invitation branch organization mismatch','cross-tenant invitation branch rejected');
select * from finish(); rollback;
